int asc(int a, int b) {
    return a - b;
}
void bubble(int *a, int n, int (*cmp)(int, int)) {
    for (int i = 0; i < n - 1; i++)
        for (int j = 0; j < n - 1 - i; j++)
            if (cmp(a[j], a[j + 1]) > 0) {
                int t = a[j];
                a[j] = a[j + 1];
