    scanf("%d", &k);
    k %= n;
    rev(a, a + n - 1);
    rev(a, a + n - k - 1);
    rev(a + n - k, a + n - 1);
    for (int i = 0; i < n; i++) {
        if (i)
            printf(" ");
        printf("%d", a[i]);
    }
    return 0;
}

