#include <stdio.h>
void qs(int *a, int n) {
    if (n <= 1)
        return;
    int pivot = a[n - 1];
    int *i = a - 1;
    for (int *j = a; j < a + n - 1; j++) {
        if (*j <= pivot) {
            i++;
            int t = *i;
            *i = *j;
            *j = t;
        }
    }
    int *pi = i + 1;
    int t = *pi;
    *pi = a[n - 1];
    a[n - 1] = t;
    qs(a, (int)(pi - a));
    qs(pi + 1, (int)((a + n) - (pi + 1)));
}
